INSERT INTO feature VALUES('gate-slots','workflow','The gate graph takes a host-wide slot',NULL,'implemented','ordinary',NULL,'`mise run check` holds one of the host''s gate slots for its whole run, the host lock `gate`: a `flock` on `gate.<n>.lock` in the user''s runtime directory that a killed gate releases. The count is `GANDR_GATE_SLOTS`, or one slot for each 8 cores without it, the count that nine rounds of four gates of a code edit select (#6699). A gate past the slots prints `gate: waiting on <holders>` and waits, or with `--no-wait` refuses at once. The mutation run and `ci:act` take their own locks through the same helper. Its one full test suite, the enforcing one, takes the host''s cores divided by the slots, never more than a smaller `NEXTEST_TEST_THREADS` the caller set. A gate first takes its lane''s one lock, so one lane runs one gate at a time, and a heavy `check:*` task run alone takes its lane''s lock and a slot through `.config/mise/gated`. The gate runs the checks the paths of the change select through `.config/gate-scope/table.json`, and `--all` runs every check.',NULL,'.config/mise/gate.bash .config/mise/gated .config/mise/host-lock.bash .config/mise/host-lock-cases.bash .config/gate-scope/table.json .config/gate-scope/select.jq .config/gate-scope/cases.json',NULL,NULL);
